referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  return d.users.map((u) => {
    const row = {};
    for (const key of d.select) row[key] = u[key];
    if (d.includePosts) row.posts = d.posts.filter((p) => p.userId === u.id).map((p) => clone(p));
    return row;
  });
}

referenceSolutions.typescript:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const clone = (v: any): any => JSON.parse(JSON.stringify(v));
  return d.users.map((u: any) => {
    const row: any = {};
    for (const key of d.select) row[key] = u[key];
    if (d.includePosts)
      row.posts = d.posts.filter((p: any) => p.userId === u.id).map((p: any) => clone(p));
    return row;
  });
}
